use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.root == -1 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur: int = self.root
        loop {
            let k = self.keys[cur]
            if x == k {
                return false
            }
            let go_left = x < k
            let next: int = if go_left { self.lefts[cur] } else { self.rights[cur] }
            if next == -1 {
                let idx: int = self.keys.len() as int
                self.keys.push(x)
                self.lefts.push(-1)
                self.rights.push(-1)
                if go_left {
                    self.lefts[cur] = idx
                } else {
                    self.rights[cur] = idx
                }
                return true
            }
            cur = next
        }
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent == -1 {
            self.root = new
        } else if self.lefts[parent] == old {
            self.lefts[parent] = new
        } else {
            self.rights[parent] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut cur: int = self.root
        let mut parent: int = -1
        while cur != -1 && self.keys[cur] != x {
            parent = cur
            if x < self.keys[cur] {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        if cur == -1 {
            return false
        }
        if self.lefts[cur] != -1 && self.rights[cur] != -1 {
            let mut sp: int = cur
            let mut s: int = self.rights[cur]
            while self.lefts[s] != -1 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[cur] = self.keys[s]
            let sr: int = self.rights[s]
            self.replace_child(sp, s, sr)
        } else {
            let child: int = if self.lefts[cur] != -1 { self.lefts[cur] } else { self.rights[cur] }
            self.replace_child(parent, cur, child)
        }
        true
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur: int = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.lefts[cur]
            }
            let n: int = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n]}")
            cur = self.rights[n]
        }
        if out.len() == 0 {
            return "<empty>"
        }
        out.join(" ")
    }

    fn height(self) -> int {
        if self.root == -1 {
            return 0
        }
        let mut best: int = 0
        let mut nodes: Vec<int> = [self.root]
        let mut depths: Vec<int> = [1]
        while nodes.len() > 0 {
            let n: int = nodes.pop().unwrap_or(-1)
            let d: int = depths.pop().unwrap_or(0)
            if d > best {
                best = d
            }
            if self.lefts[n] != -1 {
                nodes.push(self.lefts[n])
                depths.push(d + 1)
            }
            if self.rights[n] != -1 {
                nodes.push(self.rights[n])
                depths.push(d + 1)
            }
        }
        best
    }

    fn min(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.lefts[cur] != -1 {
            cur = self.lefts[cur]
        }
        "${self.keys[cur]}"
    }

    fn max(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.rights[cur] != -1 {
            cur = self.rights[cur]
        }
        "${self.keys[cur]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let arg: int = if parts.len() > 1 { parts[1].parse::<int>().unwrap_or(0) } else { 0 }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

